command:
/**
 * SVA example: Dodecahedron Toggle
 * A rotating arcane dodecahedron encloses each selected token (back layer under the token, front
 * layer over it). Run again to fade it out.
 *
 * Usage: select tokens, run. Change STYLE below.
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

// "star.blueyellow", "rune.blueyellow", "rune.dark_greenpurple", "skull.dark_greenpurple"
const STYLE = "star.blueyellow";
const [SHAPE, COLOR] = STYLE.split(".");
const SCALE = 1.6;
const FADE_MS = 500;

const tokens = canvas.tokens.controlled;
if (!tokens.length) return ui.notifications.warn("Select at least one token.");
const sceneId = canvas.scene.id;

for (const tok of tokens) {
  const name = `sva-dodecahedron:${tok.id}`;
  if (SVA.effects.list({ sceneId, name }).length) {
    await SVA.effects.end({ name, sceneId });
    continue;
  }
  const seq = SVA.sequence();
  for (const half of ["below", "above"]) {
    seq
      .effect()
      .file(`jb2a.dodecahedron.${SHAPE}.${half}.${COLOR}`)
      .attachTo(tok.id)
      .scaleToObject(SCALE)
      .layer(half === "below" ? "belowTokens" : "aboveTokens")
      .fadeIn(FADE_MS, { ease: "easeOutCubic" })
      .fadeOut(FADE_MS, { ease: "easeOutCubic" })
      .persist(true)
      .name(name);
  }
  await seq.play();
}
